import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {    public static void main(String[] args) throws IOException {        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));        StringBuilder output = new StringBuilder();        int T = Integer.parseInt(br.readLine());        while (T-- > 0) {            StringTokenizer st = new StringTokenizer(br.readLine());            int A = Integer.parseInt(st.nextToken());            int B = Integer.parseInt(st.nextToken());            int C = Integer.parseInt(st.nextToken());            int D = Integer.parseInt(st.nextToken());            int E = Integer.parseInt(st.nextToken());            boolean possible = (A <= E && (B + C) <= D) ||                             (B <= E && (A + C) <= D) ||                             (C <= E && (A + B) <= D);            if (possible) {                output.append("YES\n");            } else {                output.append("NO\n");            }        }        System.out.print(output.toString());    }}